 220	For a graded ring $S$, $\operatorname{Proj}S$ is the homogeneous-prime space excluding the irrelevant
 221	ideal, with basic opens $D_+(f)$, and structure sheaf given by degree-zero localizations.
 222	\uses{def:II-2-spectrum,def:II-1-presheaf}
 223	\end{definition}
 224	
 225	\begin{proposition}[Proj charts]
 226	\label{prop:II-2-5}
 227	\source{hartshorne-algebraic-geometry:II.2.5}
 228	\dcref{II.2.5}
 229	The $D_+(f)$ form an affine open cover of $\operatorname{Proj}S$ and
 230	$\Gamma(D_+(f),\mathcal O)=S_{(f)}$.
 231	\uses{prop:II-2-2}
 232	\end{proposition}
 233	\begin{proof}
 234	The homogeneous-prime topology is covered by $D_+(f)$ for positive-degree homogeneous $f$. Degree-zero
 235	fractions glue exactly as in Proposition \ref{prop:II-2-2}, giving the affine chart ring $S_{(f)}$.
 236	\end{proof}
 237	
 238	\begin{proposition}[Projective space represents line bundles]
 239	\label{prop:II-2-6}
 240	\source{hartshorne-algebraic-geometry:II.2.6}
 241	\dcref{II.2.6}
 242	For a field $k$, a morphism $X\to\mathbb P^n_k$ is equivalent to an invertible sheaf $L$ on $X$ and
 243	global sections $s_0,\ldots,s_n$ generating $L$, up to simultaneous multiplication by an isomorphism.
 244	\uses{def:II-2-scheme,def:II-1-subsheaf-exact}
 245	\end{proposition}
 246	\begin{proof}
 247	Pull back $\mathcal O(1)$ and its coordinate sections. Conversely, the ratios $s_i/s_j$ define compatible
 248	maps to the standard affine charts; gluing gives the morphism and the two constructions are inverse.
 249	\end{proof}
 250	
 251	\section{First Properties of Schemes}
 252	
 253	\begin{definition}[Connected, reduced, integral, normal]
 254	\label{def:II-3-properties}
 255	\source{hartshorne-algebraic-geometry:II.3}
 256	A scheme is connected or irreducible according to its topological space, reduced when all affine
 257	rings are reduced, integral when reduced and irreducible, and locally Noetherian when it has a cover
 258	by spectra of Noetherian rings. An integral scheme is normal if its local rings are integrally closed.
 259	\end{definition}
 260	
 261	\begin{proposition}[Integral schemes]
 262	\label{prop:II-3-1}
 263	\source{hartshorne-algebraic-geometry:II.3.1}
 264	\dcref{II.3.1}
 265	A scheme is integral iff it is reduced and irreducible.
 266	\end{proposition}
 267	\begin{proof}
 268	On an affine open, irreducibility says the nilradical is prime; reducedness makes it zero, so the
 269	coordinate ring is a domain. The converse follows because spectra of domains are irreducible and
 270	localization preserves domains.
1080	finite generation after shrinking.
1081	\end{proof}
1082	
1083	\begin{proposition}[Ample invertible sheaves]
1084	\label{prop:II-7-5}
1085	\source{hartshorne-algebraic-geometry:II.7.5}
1086	\dcref{II.7.5}
1087	For an invertible sheaf $\mathcal L$ on a noetherian scheme, the following are equivalent: $\mathcal L$
1088	is ample; every coherent sheaf becomes generated by global sections after a positive twist; and a
1089	sufficiently high power of $\mathcal L$ gives a projective embedding on every affine neighborhood.
1090	\end{proposition}
1091	\begin{proof}
1092	The implications follow by applying the finite-generation lemma to affine standard opens and using
1093	the point-and-tangent separation criterion.
1094	\end{proof}
1095	
1096	\begin{theorem}[Projective implies proper]
1097	\label{thm:II-7-6}
1098	\source{hartshorne-algebraic-geometry:II.7.6}
1099	\dcref{II.7.6}
1100	Every projective morphism is proper.
1101	\end{theorem}
1102	\begin{proof}
1103	The projection $\mathbb P^n_Y\to Y$ satisfies the valuative criterion by scaling homogeneous coordinates
1104	so one is a unit in the valuation ring. Closed immersions and compositions preserve properness.
1105	\end{proof}
1106	
1107	\begin{proposition}[Divisors of zeros and linear systems]
1108	\label{prop:II-7-7}
1109	\source{hartshorne-algebraic-geometry:II.7.7}
1110	\dcref{II.7.7}
1111	A nonzero section of an invertible sheaf determines an effective Cartier divisor of zeros. The
1112	complete linear system of an invertible sheaf is the projective space of its nonzero global sections,
1113	and its associated map is the map defined by those sections.
1114	\end{proposition}
1115	\begin{proof}
1116	Locally trivialize the sheaf; the section is a non-zero-divisor equation and its local equations differ
1117	by units. Ratios of a basis of global sections give the associated projective map.
1118	\end{proof}
1119	
1120	\begin{lemma}[Base-point-free linear systems]
1121	\label{lem:II-7-8}
1122	\source{hartshorne-algebraic-geometry:II.7.8}
1123	\dcref{II.7.8}
1124	A linear system has no base points precisely when its sections generate the associated invertible
1125	sheaf; in that case it defines a morphism to projective space.
1126	\uses{thm:II-7-1}
1127	\end{lemma}
1128	\begin{proof}
1129	The stalkwise generation condition is exactly the absence of a common zero, and Theorem~\ref{thm:II-7-1}
1130	then constructs the morphism.
1131	\end{proof}
1132	
